import type {AgentResponse} from '../types'

// Rough estimate of token count (4 characters per token)
const CHARACTERS_PER_TOKEN = 4

export function calculateOutputTokenUsage(pullTitleResponse: AgentResponse) {
  if (!pullTitleResponse || !pullTitleResponse.choices[0]?.message.content) {
    throw new Error('Pull title response is empty or undefined')
  }
  const chars = pullTitleResponse.choices[0].message.content.length

  return Math.ceil(chars / CHARACTERS_PER_TOKEN)
}
