import {CopilotAuthTokenProvider} from '@github-ui/copilot-auth-token'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {makeCAPIRequest} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'
// eslint-disable-next-line @github-ui/github-monorepo/restrict-relay-imports
import {CopilotChatMessageStreamer} from '@github-ui/copilot-chat/utils/copilot-chat-message-streamer'
import {useQuery} from '@github-ui/react-query'
import {sendStats} from '@github-ui/stats'
import {useClickAnalytics} from '@github-ui/use-analytics'

import type {CopilotGeneratePullTitleAuthInfo, ValidatedPullTitle, Commit, AgentResponse} from './types'
import {calculateInputTokenUsage} from './utilities/calculate-input-token-usage'
import {calculateOutputTokenUsage} from './utilities/calculate-output-token-usage'
import {createCommitReferences} from './utilities/create-commit-references'
import {handleStreamingMessage} from './utilities/handle-streaming-message'
import {validateAndExtractPullTitle} from './utilities/validate-and-extract-pull-title'

function returnFallback(defaultTitle: string): ValidatedPullTitle {
  return {
    title: defaultTitle,
  }
}

// CAPI status codes that are expected and shouldn't trigger error stats
const EXPECTED_ERROR_STATUS_CODES = [
  402, // "Payment Required" - Response when free user has hit their quota and we should restrict access
  429, // "Too Many Requests" - CAPI rate limiting response
]

function sendErrorAndLatencyStats(incrementKey: PlatformBrowserIncrementKey, startTime: number) {
  const duration = performance.now() - startTime

  sendStats({
    incrementKey,
    requestUrl: window.location.href,
  })

  sendStats({
    distributionKey: 'GENERATED_PULL_TITLE_LATENCY',
    distributionValue: Math.round(duration),
    requestUrl: window.location.href,
  })
}

export function useGeneratePullTitle(
  defaultTitle: string,
  copilotGeneratePullTitleAuthInfo?: CopilotGeneratePullTitleAuthInfo | undefined,
  commits?: Commit[],
  regenerateCallCount = 0,
) {
  // Check if we should use fallback immediately
  const shouldUseFallback =
    copilotGeneratePullTitleAuthInfo === undefined ||
    !copilotGeneratePullTitleAuthInfo.accessAllowed ||
    commits === undefined ||
    commits.length === 0

  const {sendClickAnalyticsEvent} = useClickAnalytics()
  const {data: generatedPullTitle, isFetching} = useQuery({
    queryKey: ['generate-pull-title', commits, copilotGeneratePullTitleAuthInfo, regenerateCallCount],
    queryFn: async () => {
      const startTime = performance.now()

      if (!copilotGeneratePullTitleAuthInfo || !commits) {
        throw new Error('Missing required data for pull title generation')
      }

      const authTokenProvider = new CopilotAuthTokenProvider(
        copilotGeneratePullTitleAuthInfo.ssoOrganizations.map(org => org.id),
      )
      const token = await authTokenProvider.getAuthToken()

      const references = createCommitReferences(commits)

      const result = await makeCAPIRequest({
        authToken: token,
        basePath: copilotGeneratePullTitleAuthInfo.apiUrl,
        body: {
          messages: [
            {
              role: 'user',
              content: '',
              copilot_references: references,
            },
          ],
          temperature: 0.3,
          response_format: {
            type: 'json_schema',
            json_schema: {
              description: 'The schema to abide by when generating pull request title output',
              name: 'pull_request_title_response',
              strict: true,
              schema: {
                type: 'object',
                properties: {
                  title: {
                    type: 'string',
                    description: 'The pull request title',
                  },
                },
                required: ['title'],
                additionalProperties: false,
              },
            },
          },
        },
        integrationId: 'copilot-directory',
        method: 'POST',
        path: '/agents/github-pull-request-title-generation',
        streamingResponse: true,
      })

      try {
        if (!result.ok) {
          throw new Error('Failed to generate pull request title')
        }

        const reader = result.body?.getReader()
        if (!reader) {
          throw new Error('No reader found in response body')
        }

        const streamer = new CopilotChatMessageStreamer<AgentResponse>(reader)
        const message = await handleStreamingMessage(streamer)

        const validatedTitle = validateAndExtractPullTitle(message)

        // Track successful generation
        sendErrorAndLatencyStats('GENERATED_PULL_TITLE_SUCCESS', startTime)

        // Track input/output token usage and send to hydro
        const inputTokenCount = calculateInputTokenUsage(commits)
        const outputTokenCount = calculateOutputTokenUsage(message)
        const eventData = {
          category: 'copilot_generate_pull_title',
          action: 'generate',
          input_token_count: inputTokenCount,
          output_token_count: outputTokenCount,
          total_token_count: inputTokenCount + outputTokenCount,
        }
        sendClickAnalyticsEvent(eventData)

        if (validatedTitle) {
          return validatedTitle
        } else {
          return returnFallback(defaultTitle)
        }
      } catch {
        // Track general errors (network, auth, etc.)
        // Don't send error stats for expected quota/auth errors
        if (!EXPECTED_ERROR_STATUS_CODES.includes(result.status)) {
          sendErrorAndLatencyStats('GENERATED_PULL_TITLE_ERROR', startTime)
        }
        return returnFallback(defaultTitle)
      }
    },
    enabled: !shouldUseFallback && regenerateCallCount > 0,
    meta: {action: 'get-generated-pull-title'},
  })

  // Return fallback immediately if conditions are not met
  if (shouldUseFallback) {
    return {
      generatedPullTitle: returnFallback(defaultTitle),
      isFetching: false,
    }
  }

  return {generatedPullTitle, isFetching}
}
