import type {AgentResponse, ValidatedPullTitle} from '../types'

export function validateAndExtractPullTitle(agentResponse: AgentResponse): ValidatedPullTitle | undefined {
  const pullTitleResponse = agentResponse?.choices?.[0]?.message

  if (!pullTitleResponse) {
    throw new Error('No message found in agent response')
  }

  if (!pullTitleResponse.content) {
    throw new Error('No content found in pull title response')
  }

  let parsedContent: {title: string}

  try {
    parsedContent = JSON.parse(pullTitleResponse.content)
  } catch {
    throw new Error('Invalid JSON in pull title response')
  }

  // The 'title' field is required by schema; no need to check for undefined or null.
  if (parsedContent.title.trim() === '') return

  return {
    title: parsedContent.title,
  }
}
